/// <summary>
/// Extension of class WHSBillOfLadingDP
/// </summary>
[ExtensionOf(classStr(WhsBillOfLadingDP))]
final public class AVAWhsBillOfLadingDPCls_Extension
{
    public AVAWHSBillOfLadingContainerTmp   avaLadingContainerTmp;
    public AVAWHSBillOfLadingPackingSlipTmp avaLadingPackingSlipTmp;
    public boolean avaContainerTmpFlag = true;

}

