/// <summary>
/// Extension of initializeWHSBillOfLadingTmp method
/// </summary>
/// <param name = "_rowNum">int</param>
protected void initializeWHSBillOfLadingTmp(int _rowNum)
{
    next initializeWHSBillOfLadingTmp(_rowNum);

    TMSCarrier              avaCarrier          = TMSCarrier::find(whsBillOfLadingTmp.CarrierCode);
    WHSShipmentTable        avaShipmentTable    = WHSShipmentTable::find(billOfLading.ShipmentId);
    LogisticsPostalAddress  carrierAddress      = TMSCarrier::avaPrimaryPostalAddress(avaCarrier.RecId);
    LogisticsPostalAddress  shippingAddress     = LogisticsPostalAddress::findRecId(billOfLading.ShippingPostalAddress);
    LogisticsPostalAddress  deliveryAddress     = LogisticsPostalAddress::findRecId(billOflading.DeliveryPostalAddress);
    LogisticsPostalAddress  avaOrderAddress     = this.avaOrderAddress();

    LogisticsLocation       carrierChild        = LogisticsLocation::findElectronicLocationByParent(carrierAddress.Location);
    LogisticsLocation       shippingChild       = LogisticsLocation::findElectronicLocationByParent(shippingAddress.Location);
    LogisticsLocation       dlvChild            = LogisticsLocation::findElectronicLocationByParent(deliveryAddress.Location);


    whsBillOfLadingTmp.AVAFromAddress           = shippingAddress.Address;
    whsBillOfLadingTmp.AVAFromCountry           = shippingAddress.CountryRegionId;
    whsBillOfLadingTmp.AVAFromDate              = DateTimeUtil::date(billOfLading.CreatedDateTime);

    whsBillOfLadingTmp.AVAToAddress             = deliveryAddress.Address;
    whsBillOfLadingTmp.AVAToCountry             = deliveryAddress.CountryRegionId;
    whsBillOfLadingTmp.AVAToPhone               = this.avaOrderPhone();
    whsBillOfLadingTmp.AVAToEmail               = this.avaOrderEmail();

    whsBillOfLadingTmp.AVACarrierAddress        = carrierAddress.Address;
    whsBillOfLadingTmp.AVACarrierName           = carrierAddress.NDXLogisticsLocationName1;
    whsBillOfLadingTmp.AVACarrierStreet         = carrierAddress.Street;
    whsBillOfLadingTmp.AVACarrierCity           = carrierAddress.City;
    whsBillOfLadingTmp.AVACarrierState          = carrierAddress.State;
    whsBillOfLadingTmp.AVACarrierZipCode        = carrierAddress.ZipCode;
    whsBillOfLadingTmp.AVACarrierCountry        = carrierAddress.CountryRegionId;
    whsBillOfLadingTmp.AVACarrierPhone          = strFmt("@NDX:NXAVar1SpaceVar2", LogisticsElectronicAddress::findPrimary(carrierChild.RecId, LogisticsElectronicAddressMethodType::Phone).Locator, LogisticsElectronicAddress::findPrimary(carrierChild.RecId, LogisticsElectronicAddressMethodType::Phone).LocatorExtension);;
    whsBillOfLadingTmp.AVACarrierEmail          = LogisticsElectronicAddress::findPrimary(carrierChild.RecId, LogisticsElectronicAddressMethodType::Email).Locator;

    whsBillOfLadingTmp.AVAOrderAddress          = avaOrderAddress.Address;
    whsBillOfLadingTmp.AVAOrderName             = this.avaOrderName();

    whsBillOfLadingTmp.AVAVendAccount           = TMSCarrier::find(billOfLading.CarrierCode).VendorCode;
    whsBillOfLadingTmp.AVAShippingPhone         = strFmt("@NDX:NXAVar1SpaceVar2", LogisticsElectronicAddress::findPrimary(shippingChild.RecId, LogisticsElectronicAddressMethodType::Phone).Locator, LogisticsElectronicAddress::findPrimary(shippingChild.RecId, LogisticsElectronicAddressMethodType::Phone).LocatorExtension);
    whsBillOfLadingTmp.AVAShippingMail          = LogisticsElectronicAddress::findPrimary(shippingChild.RecId, LogisticsElectronicAddressMethodType::Email).Locator;

    whsBillOfLadingTmp.AVADlvDate                   = DateTimeUtil::date(avaShipmentTable.whsLoadTable().LoadArrivalUTCDateTime);
    whsBillOfLadingTmp.AVALoadingMeterHeader        = avaShipmentTable.whsLoadTable().AVALoadingMeter;
    whsBillOfLadingTmp.AVAPrintStatisticCodeHeader  = avaShipmentTable.whsLoadTable().AVAPrintStatisticCode;
    whsBillOfLadingTmp.DlvTermId                    = avaShipmentTable.DlvTermId;

    if(avaShipmentTable.WorkTransType == WHSWorkTransType::Sales
        && avaShipmentTable.OrderNum != '')
    {
        whsBillOfLadingTmp.AVAInfoField3        = this.avaGetInfoField3();
        whsBillOfLadingTmp.AVAORderPackingSlip  = this.avaOrderLastPackingSlip();
    }

    if(billOfLading.MasterBillOfLadingId && !billOfLading.MasterBOLFlag)
    {
        WHSBillOfLadingTmp.MasterBillOfLadingId = billOfLading.MasterBillOfLadingId;
    }

    if(avaContainerTmpFlag)
    {
        this.avaCreateLadingContainerTmpLines();
        this.avaCreatePackingSlipTmpLines();

        avaContainerTmpFlag = false;
    }
}

/// <summary>
/// returns a summarized note of all InfoFields3 for all salesOrders of the current LoadId
/// </summary>
/// <returns>Notes</returns>
public Notes avaGetInfoField3()
{
    WHSShipmentTable            whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    WHSLoadLine                 whsLoadLineLoc;
    SalesLine                   salesLineLoc;
    KCS_SOCSalesTableInfoFields locSalesTableInfoFields;

    Notes locInfoField3;

    while select salesLineLoc
        group by SalesId
        join whsLoadLineLoc
        where salesLineLoc.InventTransId    == whsLoadLineLoc.InventTransId
        && whsLoadLineLoc.InventTransType   == InventTransType::Sales
        && whsLoadLineLoc.LoadId            == whsShipmentTableLoc.LoadId
    {
        locSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, salesLineLoc.SalesId);

        if(locSalesTableInfoFields.InfoField3 == '')
        {
            continue;
        }
        else if(locInfoField3 != '')
        {
            locInfoField3 += '\n';
        }

        locInfoField3 += locSalesTableInfoFields.InfoField3;
    }

    return locInfoField3;
}

/// <summary>
/// Gets the LastPackingSlipId from sales order
/// </summary>
/// <returns>LastPackingSlipId</returns>
public LastPackingSlipId avaOrderLastPackingSlip()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    LastPackingSlipId   avaLastPackingSlip;

    if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::Sales)
    {
        return SalesTable::find(whsShipmentTableLoc.OrderNum).lastPackingSlip();
    }

    return avaLastPackingSlip;
}

/// <summary>
/// Gets the LogisticsPostalAddressRecord for sales and transfer records
/// </summary>
/// <returns>LogisticsPostalAddress</returns>
public LogisticsPostalAddress avaOrderAddress()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    LogisticsPostalAddress postalAddressLoc;

    if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::Sales)
    {
        return SalesTable::find(whsShipmentTableLoc.OrderNum).custTable_CustAccount().postalAddress();
    }
    else if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::TransferIssue)
    {
        InventTransferTable transferTableLoc = InventTransferTable::find(whsShipmentTableLoc.OrderNum);

        return LogisticsPostalAddress::findRecId(transferTableLoc.FromPostalAddress);
    }

    return postalAddressLoc;
}

/// <summary>
/// Gets the names of the LogisticsPostalAddress/CustTable records
/// </summary>
/// <returns>Name</returns>
public Name avaOrderName()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    Name nameLoc;

    if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::Sales)
    {
        return SalesTable::find(whsShipmentTableLoc.OrderNum).custTable_CustAccount().avaName();
    }
    else if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::TransferIssue)
    {
        InventTransferTable transferTableLoc = InventTransferTable::find(whsShipmentTableLoc.OrderNum);

        return LogisticsPostalAddress::findRecId(transferTableLoc.FromPostalAddress).avaName();
    }

    return nameLoc;
}

/// <summary>
/// Gets the phone of the SalesTable records
/// </summary>
/// <returns>phone</returns>
public Phone avaOrderPhone()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    Phone phoneLoc;

    if(whsShipmentTableLoc.WorkTransType == WHSWorkTransType::Sales)
