/// <summary>
/// calls all methods to create the different AVAWHSBillOfLadingPackingSLipTmp records
/// </summary>
public void avaCreatePackingSlipTmpLines()
{
    this.avaCreatePackingSlipTmpLines_Sales();
    this.avaCreatePackingSlipTmpLines_Material();
    this.avaCreatePackingSlipTmpLines_Transfer();
}

/// <summary>
/// Cycles through records to create sales AVAWHSBillOfLadingPackingSlipTmp records
/// </summary>
public void avaCreatePackingSlipTmpLines_Sales()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    WHSLoadTable        whsLoadTableLoc     = whsShipmentTableLoc.whsLoadTable();
    WHSLoadLine         whsLoadLineLoc;
    SalesLine           salesLineLoc;
    SalesTable          salesTableLoc;
    Set                 avaPackingSet       = new Set(Types::String);

    ttsbegin;

    while select salesLineLoc
        group by SalesId, LineNum, InventTransId
        join salesTableLoc
        join whsLoadLineLoc
        where salesLineLoc.InventTransId    == whsLoadLineLoc.InventTransId
        && salesTableLoc.SalesId            == salesLineLoc.SalesId
        && salesTableLoc.PurchOrderFormNum  == ''
        && whsLoadLineLoc.InventTransType   == InventTransType::Sales
        && whsLoadLineLoc.LoadId            == whsLoadTableLoc.LoadId
    {
        PackingSlipId avaPackingSlipIdLoc = salesLineLoc.lastPackingSlip();

        if(!avaPackingSet.in(avaPackingSlipIdLoc))
        {
            avaPackingSet.add(avaPackingSlipIdLoc);
            this.avaCreatePackingSlipTmpLine_Sales(salesLineLoc);
        }
    }

    ttscommit;
}

/// <summary>
/// inserts the sales AVAWHSBillOfLadingPackingSlipTmp
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
public void avaCreatePackingSlipTmpLine_Sales(SalesLine _salesLine)
{
    avaLadingPackingSlipTmp.clear();

    this.avaInitializePackingSlipTmpLine_Sales(_salesLine);

    avaLadingPackingSlipTmp.insert();
}

/// <summary>
/// initializes the values for the sales AVAWHSBillOfLadingPackingSlipTmp records
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
public void avaInitializePackingSlipTmpLine_Sales(SalesLine _salesLine)
{
    avaLadingPackingSlipTmp.CustomerRef         = _salesLine.salesTable().CustomerRef;
    avaLadingPackingSlipTmp.Id                  = _salesLine.SalesId;
    avaLadingPackingSlipTmp.PackingSlipId       = _salesLine.lastPackingSlip();
    avaLadingPackingSlipTmp.PackingSlipType     = AVAWHSBillOfLadingPackingSlipType::Sales;
    avaLadingPackingSlipTmp.PurchOrderFormNum   = _salesLine.salesTable().PurchOrderFormNum;
}

/// <summary>
/// Cycles through records to create material AVAWHSBillOfLadingPackingSlipTmp records
/// </summary>
public void avaCreatePackingSlipTmpLines_Material()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    WHSLoadTable        whsLoadTableLoc     = whsShipmentTableLoc.whsLoadTable();
    WHSLoadLine         whsLoadLineLoc;
    SalesLine           salesLineLoc;
    SalesTable          salesTableLoc;
    Set                 avaPackingSet       = new Set(Types::String);

    ttsbegin;

    while select salesLineLoc
        group by SalesId, LineNum, InventTransId
        join salesTableLoc
        join whsLoadLineLoc
        where salesLineLoc.InventTransId    == whsLoadLineLoc.InventTransId
        && salesTableLoc.SalesId            == salesLineLoc.SalesId
        && salesTableLoc.PurchOrderFormNum  != ''
        && whsLoadLineLoc.InventTransType   == InventTransType::Sales
        && whsLoadLineLoc.LoadId            == whsLoadTableLoc.LoadId
    {
        PackingSlipId avaPackingSlipIdLoc = salesLineLoc.lastPackingSlip();

        if(!avaPackingSet.in(avaPackingSlipIdLoc))
        {
            avaPackingSet.add(avaPackingSlipIdLoc);
            this.avaCreatePackingSlipTmpLine_Material(salesLineLoc);
        }
    }    

    ttscommit;
}

