/// <summary>
/// Cycles through records to create inventTransfer AVAWHSBillOfLadingPackingSlipTmp records
/// </summary>
public void avaCreatePackingSlipTmpLines_Transfer()
{
    WHSShipmentTable    whsShipmentTableLoc = WHSShipmentTable::find(billOfLading.ShipmentId);
    WHSLoadTable        whsLoadTableLoc     = whsShipmentTableLoc.whsLoadTable();
    WHSLoadLine         whsLoadLineLoc;
    InventTransferJour  inventTransferJourLoc;
    InventTransferLine  inventTransferLineLoc;
    Set                 avaPackingSet       = new Set(Types::String);

    ttsbegin;

    while select inventTransferLineLoc
        group by TransferId, LineNum
        join whsLoadLineLoc
        where inventTransferLineLoc.InventTransId   == whsLoadLineLoc.InventTransId
        &&    whsLoadLineLoc.InventTransType        == InventTransType::TransferOrderShip
        &&    whsLoadLineLoc.LoadId                 == whsLoadTableLoc.LoadId
    {
        Voucher avaVoucherIdLoc = inventTransferLineLoc.avaLastTransferJournal().VoucherId;

        if(!avaPackingSet.in(avaVoucherIdLoc))
        {
            avaPackingSet.add(avaVoucherIdLoc);
            this.avaCreatePackingSlipTmpLine_Transfer(inventTransferLineLoc);
        }

    }

    ttscommit;
}

    /// <summary>
    /// inserts the inventTransfer AVAWHSBillOfLadingPackingSlipTmp
    /// </summary>
/// <param name = "_transferLine">InventTransferLine</param>
    public void avaCreatePackingSlipTmpLine_Transfer(InventTransferLine _transferLine)
    {
        avaLadingPackingSlipTmp.clear();

        this.avaInitializePackingSlipTmpLine_Transfer(_transferLine);

        avaLadingPackingSlipTmp.insert();
    }

/// <summary>
/// initializes the values for the inventTransfer AVAWHSBillOfLadingPackingSlipTmp records
/// </summary>
/// <param name = "_transferLine">InventTransferLine</param>
public void avaInitializePackingSlipTmpLine_Transfer(InventTransferLine _transferLine)
{
    avaLadingPackingSlipTmp.Id                  = _transferLine.InventTransId;
    avaLadingPackingSlipTmp.PackingSlipId       = _transferLine.avaLastTransferJournal().VoucherId;
    avaLadingPackingSlipTmp.PackingSlipType     = AVAWHSBillOfLadingPackingSlipType::InventTransfer;
}

/// <summary>
/// Loops through all WHSContainerTable records for all Shiments with the same LoadId
/// </summary>
public void avaCreateLadingContainerTmpLines()
{
    WHSShipmentTable whsShipmentTableLoc    = WHSShipmentTable::find(billOfLading.ShipmentId);
    WHSLoadTable    whsLoadTableLoc            = whsShipmentTableLoc.whsLoadTable();
    WHSContainerTable whsContainerTableLoc;

    whsShipmentTableLoc.clear();

    ttsbegin;

    while select sum(Weight), count(RecId), ContainerTypeCode from whsContainerTableLoc
        group by whsContainerTableLoc.ContainerTypeCode, whsShipmentTableLoc.OrderNum
        join OrderNum from WHSShipmentTableLoc
        where whsContainerTableLoc.ShipmentId == whsShipmentTableLoc.ShipmentId
        && whsShipmentTableLoc.LoadId == whsLoadTableLoc.LoadId
    {
        this.avaCreateLadingContainerTmpLine(whsContainerTableLoc, whsShipmentTableLoc);
    }

    ttscommit;
}

/// <summary>
/// create AVAWHSBillOfLadingContainerTmp record
/// </summary>
/// <param name = "_containerTable">WHSContainerTable</param>
/// <param name = "_whsShipmentTable">WHSShipmentTable</param>
public void avaCreateLadingContainerTmpLine(WHSContainerTable _containerTable, WHSShipmentTable _whsShipmentTable)
{
    avaLadingContainerTmp.clear();

    this.avaInitializeContainerTmp(_containerTable, _whsShipmentTable);

    avaLadingContainerTmp.insert();
}

/// <summary>
/// Initialize AVAWHSBillOfLadingContainerTmp record
/// </summary>
/// <param name = "_containerTable">WHSContainerTable</param>
/// <param name = "_whsShipmentTable">WHSShipmentTable</param>
public void avaInitializeContainerTmp(WHSContainerTable _containerTable, WHSShipmentTable _whsShipmentTable)
{
    WHSContainerType containerTypeLoc   = WHSContainerType::find(_containerTable.ContainerTypeCode);

    avaLadingContainerTmp.ContainerType         = containerTypeLoc.containerTypeCode;
    avaLadingContainerTmp.OrderNum              = _whsShipmentTable.OrderNum;
    avaLadingContainerTmp.Description           = containerTypeLoc.Description;
    avaladingContainerTmp.ContainerHeight       = containerTypeLoc.ContainerHeight;
    avaladingContainerTmp.ContainerLength       = containerTypeLoc.ContainerLength;
    avaladingContainerTmp.ContainerWidth        = containerTypeLoc.ContainerWidth;
    avaladingContainerTmp.ContainerVolume       = containerTypeLoc.ContainerVolume;
    avaLadingContainerTmp.CommodityCodes        = this.containerLineCommodityCodes(_containerTable, _whsShipmentTable.OrderNum);        
    avaLadingContainerTmp.NumOfContainers       = _containerTable.RecId;
    avaLadingContainerTmp.NMFCCode              = WHSNMFC::find(whsBillOfLadingTmp.NMFCCode).Name;
    avaLadingContainerTmp.SumWeight             = _containerTable.Weight;
}

/// <summary>
/// creates a FreeText containing all commodity codes of the container line items
/// </summary>
/// <param name = "_containerTable">WHSContainerTable</param>
/// <param name = "_orderNum">WHSOrderNum</param>
/// <returns>FreeTxt</returns>
public FreeTxt containerLineCommodityCodes(WHSContainerTable _containerTable, WHSOrderNum _orderNum)
{
    WHSContainerLine    containerLineLoc;
    WHSContainerTable   containerTableLoc;
    WHSShipmentTable    whsShipmentTableLoc;
    FreeTxt             containerCommodityCodeLoc;
    InventTable         inventTableLoc;

    while select inventTableLoc
        group by inventTableLoc.IntrastatCommodity
        join containerLineLoc
        join whsShipmentTableLoc
        join containerTableLoc
        where inventTableLoc.ItemId == containerLineLoc.ItemId
            && containerLineLoc.ShipmentId == whsShipmentTableLoc.ShipmentId
            && containerTableLoc.ContainerId == containerLineLoc.ContainerId
            && whsShipmentTableLoc.OrderNum == _orderNum
            && containerTableLoc.ContainerTypeCode == _containerTable.ContainerTypeCode
            && inventTableLoc.IntrastatCommodity != 0
    {
        if(containerCommodityCodeLoc != '')
        {
            containerCommodityCodeLoc += ', ';
        }

        containerCommodityCodeLoc += EcoResCategory::find(inventTableLoc.IntrastatCommodity).Code;
    }

    return containerCommodityCodeLoc;
}
